import pathlib, json, sys
SRC = pathlib.Path(__file__).parent / "src"
def opt(glob, old, new):
    p = next(SRC.glob(glob)); s = p.read_text()
    a = "- " + json.dumps(old, ensure_ascii=False); b = "- " + json.dumps(new, ensure_ascii=False)
    if s.count(a) != 1: print("NOT FOUND/AMBIG", glob, old[:50]); return
    p.write_text(s.replace(a, b))
E = []
def app(g, old, suffix): E.append((g, old, old + suffix))
def rep(g, old, new): E.append((g, old, new))
